#!/usr/bin/env bash
# Compiles and installs the vendored r5900:LE:32:default language over the
# ghidra-emotionengine-reloaded extension that ships it.
#
# The language is that extension's (Apache-2.0, see LICENSE.emotionengine-reloaded)
# with the VU0 macro-mode semantics replaced by lane-wise float p-code
# (vulanes.sinc / vuupper.sinc, generated by gen_vu.py; docs/console-research.md,
# "PS2 VU0 macro mode"). The script regenerates those two files, checks they match
# the generator, compiles r5900.slaspec -> r5900.sla with the pinned sleigh
# compiler and copies the sources, the spec files of this directory and the .sla to
#   $GHIDRA/Ghidra/Extensions/ghidra-emotionengine-reloaded/data/languages/
#
# Usage: native/languages/r5900/install.sh [GHIDRA_INSTALL_DIR]
#   default: $ROMWRIGHT_GHIDRA or ~/ghidra_12.1.3_PUBLIC
# An import cache entry keyed on the old .sla is not reused (import_cache.rs hashes the
# language files), so a re-import is all a new .sla needs.

# The build itself is packaging/languages.py (Python, so the same code runs on
# Windows, Linux and macOS; `python setup.py` and the release workflow call it
# for all languages at once). This script installs r5900:LE:32:default alone, always
# recompiling, into GHIDRA_INSTALL_DIR (a full Ghidra install, whose own sleigh
# compiler is used, or the data directory `setup.py` made).
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/../../.." && pwd)"
GHIDRA="${1:-${ROMWRIGHT_GHIDRA:-$HOME/ghidra_12.1.3_PUBLIC}}"
exec "${PYTHON:-python3}" "$ROOT/packaging/languages.py" --ghidra "$GHIDRA" --only r5900 --force
